from PyQt5 import QtWidgets, uic

def verif(x):
    if len(x)!=0 :
        for i in range(len(x)):
            if x[i] in {'X','D','L','M','C','V','I'}:
                return True
            else:
                return False
    else:
        return False
    
def convert(x):
    R = 0
    if x == 'M' :
        R = 1000
    elif x == 'D' :
        R = 500
    elif x == 'C' :
        R = 100
    elif x == 'L' :
        R = 50
    elif x == 'X' :
        R = 10
    elif x == 'V' :
        R = 5
    elif x == 'I' :
        R = 1
    return R
def Romain(a):
    if verif(a):
        S = 0
        for i in range(len(a)-1):
            if convert(a[i]) < convert(a[i+1]) :
                S += -convert(a[i])
            else :
                S += convert(a[i])
        S += convert(a[len(a)-1])
        p.t2.setText(str(S))   
    else:
        p.t2.setText("INPUT ERROR")         
def Effacer():
    p.t1.setText("")
    p.t2.setText("")
    p.t1.setFocus()
    
app = QtWidgets.QApplication([])
p=uic.loadUi("chiffres_romains.ui")
p.show()
p.pb1.clicked.connect(lambda:Romain(p.t1.text()))
p.pb2.clicked.connect(Effacer)
app.exec_()

